# @!method self.call(user, actor, directory, target_directory, document_action_params, options)
#     `:keep_own_document_sealed`
def initialize(user, actor, directory, target_directory, document_action_params, options)
  @user = user
  @actor = actor
  @directory = directory
  @target_directory = target_directory
  @document_action_params = document_action_params
  @sealed = options[:sealed]
  @detach_organizers = options[:detach_organizers]
  # No default: a client mismatch alone is not the answer — `ClassifyDirectories` also weighs the
  # `document_move_to_anotner_client_target_directory` flag, and only its verdict knows whether
  # the move was opened at all.
  @cross_client = options.fetch(:cross_client)
  @keep_own_document_sealed = options.fetch(:keep_own_document_sealed) { target_directory.client_has_read_write_access? && !@sealed }
  # Captured before `rebind_directory!` overwrites them.
  @source_client_id = directory.client_id
  @source_client = directory.client
  @source_updated_at = directory.updated_at
end

# @!method self.call(current_fm_user, document, params = {}, action_params = {}, options = {})
#
#
def initialize(current_fm_user, document, params = {}, action_params = {}, options = {})
  @current_fm_user = current_fm_user
  @document = document
  @signature_request = @document.signature_request
  @params = params
  @signer = resolve_signer(@document, @signature_request, @params)
  @current_user = @signer&.user
  @current_actor = @signer ? TaxPreparation::SignersHelper.find_actor_for_signing(@signer, @document) : nil
  @action_params = action_params.merge(signer: @signer, user: @current_fm_user)
  @client_timezone_offset = options[:client_timezone_offset] || 0
  @options = options.merge(signer: @signer, exclude_notification_user_ids: [current_fm_user.id], skip_trd_guard: true, offline: true)
end

# @!method self.call(user, actor, directory, target_directory, verdict, document_action_params)
def initialize(user, actor, directory, target_directory, verdict, document_action_params)
  @user = user
  @actor = actor
  @directory = directory
  @target_directory = target_directory
  @cross_client = verdict[:cross_client] && directory.client_id != target_directory.client_id
  @rebind_options = {
    sealed: verdict[:sealed],
    detach_organizers: verdict[:detach_organizers],
    cross_client: @cross_client,
    keep_own_document_sealed: verdict[:keep_own_document_sealed]
  }
  @refusal = verdict[:refusal]
  @document_action_params = document_action_params
end

# @!method self.call(current_user, current_actor, current_firm, params)
def initialize(current_user, current_actor, current_firm, params)
  @current_user = current_user
  @current_actor = current_actor
  @current_firm = current_firm

  @requested_plan = params[:plan] || current_firm.plan
  @requested_seat_pools = params[:seats]
  @current_seat_pools = params[:current_seats] || []
  @visible_full_purchase_intervals = @requested_seat_pools.filter_map { _1[:interval].presence }.presence || %w[month year]
end

