# @!method self.call(actor, directories, target_directory)
#     `cross_client`, `sealed`, `keep_own_document_sealed`, `detach_organizers`, `refusal`
def initialize(actor, directories, target_directory)
  @actor = actor
  @directories = directories
  @target_directory = target_directory
  @cross_client = cross_client_allowed? && directories.any? { |directory| directory.client_id != target_directory.client_id }
  @target_child_names = target_directory.children.pluck(:name).to_set
end

# Extract data needed for skipped automations notification
def skipped_automations_notification_data(job, automations_results)
  return if automations_results.blank?

  items = automations_results.filter_map do |automation|
    context = automation.dig(:data, :skipped_automation_context)
    next unless context
    {name: automation[:name], errors: context}
  end
  return if items.empty?

  errors = {automations: items}

  {
    job_id: job.id,
    client_id: job.client.id,
    automations: reasons_from_automations_errors(errors)
  }
end

