#   invoice, and the letter states a payment, so the issued total is the wrong figure here.
def payment_receipt_notification(firm, invoice, amount_paid)
  @firm = firm
  @localized_amount = formatted_amount(amount_paid, invoice.currency, firm.locale)
  @paid_at = I18n.l(invoice.paid_at.to_date, format: :date_default)

  params = {to: firm.owner.email}
  send_mail(firm, :firm, params)
end

