def get_proposal(firm:, user:, actor:, id:)
  FirmContext.with_firm(firm.id) do
    result = GettingPaid::Proposals::Get.call(user, actor, firm, id)

    if result.failed?
      {success: false, errors: result.errors, reason: GET_PROPOSAL_REASON_MAP.fetch(result.reason), data: nil}
    else
      {success: true, errors: {}, data: proposal_attrs(result.data)}
    end
  end
end

