# Import QBO Classes
#
#
def import_classes!(connection, qbo_collection)
  adapter = Platform::FeatureFlags.feature_available?(:bookkeeping_hub_json_api, connection.firm) ? Bookkeeping::QBO::Models::SyncIn::ClassAdapter : Bookkeeping::QBO::Models::ClassAdapter
  attributes = qbo_collection.map { |transaction_class| adapter.new(transaction_class).as_attributes(connection) }

  Bookkeeping::QBO::TransactionClass.import attributes, validate: false, on_duplicate_key_update: {conflict_target: %i[connection_id qbo_id], columns: :all}
end

def clone_template(firm:, user:, actor:, template_type:, template_id:, source_firm_id:, name: nil)
  FirmContext.with_firm(firm.id) do
    result = Workflow::Templates::CloneByType.call(user, actor, template_type, template_id, source_firm_id, name: name)

    if result.successful?
      {success: true, errors: {}, reason: nil, data: {template_id: result.data.id}}
    else
      {success: false, errors: result.errors, reason: CLONE_TEMPLATE_REASON_MAP.fetch(result.reason), data: nil}
    end
  end
end

